<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, listData } from '../api'

const rows = ref([]), error = ref(''), query = ref(''), showForm = ref(false), orders = ref([])
const form = reactive({ transaction_no: '', transaction_date: new Date().toISOString().slice(0, 10), kind: 'period_expense', direction: 'expense', category: '期间费用', amount: '', currency: 'CNY', exchange_rate: '1', payment_method: '', reference: '', notes: '', order: null })
async function load() { try { rows.value = listData(await api.get('/transactions/', { params: query.value ? { search: query.value } : {} })) } catch (err) { error.value = err.message } }
async function searchOrders() { orders.value = listData(await api.get('/orders/', { params: { search: query.value } })) }
function chooseOrder(row) { form.order = row.id; form.category = '订单费用'; form.kind = 'order_expense'; orders.value = [] }
async function save() { try { await api.post('/transactions/', form); showForm.value = false; await load() } catch (err) { error.value = err.message } }
onMounted(load)
</script>
<template><section class="txn"><header><div><h2>财务流水</h2><p>统一登记实际收付款、订单费用与期间费用。</p></div><button @click="showForm = true">新增记账</button></header><div class="toolbar"><input v-model="query" placeholder="搜索流水号、客户、订单" @keyup.enter="load"><button @click="load">搜索</button></div><p v-if="error" class="error">{{ error }}</p><table><thead><tr><th>日期</th><th>流水号</th><th>类型</th><th>关联订单</th><th>原币金额</th><th>人民币</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.transaction_date }}</td><td>{{ row.transaction_no }}</td><td>{{ row.kind }}</td><td>{{ row.order_no || '—' }}</td><td>{{ row.currency }} {{ row.amount }}</td><td>¥{{ row.rmb_amount }}</td></tr></tbody></table><div v-if="showForm" class="mask" @click.self="showForm=false"><form class="dialog" @submit.prevent="save"><h3>新增财务流水</h3><label>类型<select v-model="form.kind" @change="form.direction=form.kind==='customer_receipt'?'income':'expense'"><option value="customer_receipt">客户收款</option><option value="supplier_payment">供应商付款</option><option value="order_expense">订单费用</option><option value="period_expense">期间费用</option></select></label><label>日期<input v-model="form.transaction_date" type="date" required></label><label>分类<input v-model="form.category" required></label><label>原币金额<input v-model="form.amount" type="number" step="0.01" required></label><label>币种<input v-model="form.currency" required></label><label>结汇汇率<input v-model="form.exchange_rate" type="number" step="0.000001" required></label><div v-if="form.kind==='order_expense'"><label>订单搜索<input v-model="query" placeholder="客户或订单号" @input="searchOrders"></label><button v-for="row in orders" :key="row.id" type="button" class="order" @click="chooseOrder(row)">{{ row.customer_name }}｜{{ row.customer_country || '—' }}｜{{ row.order_no }}｜{{ row.currency }} {{ row.total_amount }}</button><p v-if="form.order">已选择订单 ID：{{ form.order }}</p></div><footer><button type="button" @click="showForm=false">取消</button><button>保存</button></footer></form></div></section></template>
<style scoped>.txn{padding:34px}.txn>header{display:flex;justify-content:space-between}.txn h2{margin:0}.txn p{color:#718078}.txn button{padding:8px 13px;border:1px solid #d8e1dd;border-radius:8px;background:#fff}.toolbar{display:flex;gap:8px;margin:20px 0}.toolbar input{padding:9px;min-width:280px;border:1px solid #d8e1dd;border-radius:8px}table{background:#fff;width:100%;border-collapse:collapse;border:1px solid #e2e8e4}th,td{padding:12px;text-align:left;border-bottom:1px solid #edf1ee}.mask{position:fixed;inset:0;background:#10261d66;display:grid;place-items:center;z-index:30}.dialog{background:#fff;padding:24px;border-radius:14px;width:min(500px,calc(100vw - 32px))}.dialog label{display:grid;gap:5px;margin:10px 0}.dialog input,.dialog select{padding:9px;border:1px solid #d8e1dd;border-radius:7px}.dialog footer{display:flex;justify-content:end;gap:8px;margin-top:18px}.order{display:block;width:100%;text-align:left;margin:5px 0}.error{color:#b42318}</style>
